package mage.player.ai;
import mage.Mana;import mage.abilities.*;import mage.cards.Card;import mage.constants.*;import mage.game.permanent.Permanent;import java.util.*;
import static mage.player.ai.FourthSeatRealGameTest.check;import static mage.player.ai.RecoveryChecks.*;
public final class FourthSeatRecoveredManaTest {
 public static void main(String[]args)throws Exception{
  for(boolean input:new boolean[]{false,true})run("Floating input Selvala then real outer cast input="+input,()->{FourthSeatRealGameTest.Fixture f=fixture("a.AesiTyrantOfGyreStrait","Aesi, Tyrant of Gyre Strait");f.board("y.YevaNaturesHerald","Yeva, Nature's Herald");Permanent selvala=f.board("s.SelvalaHeartOfTheWilds","Selvala, Heart of the Wilds");f.board("basiclands.Island","Island");Card c=f.hand("g.GarruksUprising","Garruk's Uprising");if(input)f.bot.getManaPool().addMana(Mana.GreenMana(1),f.game,c.getSpellAbility());if(!input)reject(f,c);else{check(f.bot.priority(f.game),"No real Selvala funding action");check(f.game.getState().getZone(c.getId())==Zone.HAND&&f.game.getPermanent(selvala.getId()).isTapped(),"Prefunding did not return separately");check(f.bot.getManaPool().getMana().count()==4,"Selvala production/input payment incorrect");cast(f,c,2);}});
  run("Two-stage Ring Nykthos conversion funds hybrid creature",()->{FourthSeatRealGameTest.Fixture f=fixture("a.AesiTyrantOfGyreStrait","Aesi, Tyrant of Gyre Strait");f.board("y.YevaNaturesHerald","Yeva, Nature's Herald");f.board("e.EmeraldMedallion","Emerald Medallion");f.board("basiclands.Forest","Forest");f.board("basiclands.Forest","Forest");Permanent ring=f.board("s.SolRing","Sol Ring"),nyk=f.board("n.NykthosShrineToNyx","Nykthos, Shrine to Nyx");Card c=f.hand("m.MurkfiendLiege","Murkfiend Liege");check(f.bot.priority(f.game),"No Ring feeder");check(f.game.getPermanent(ring.getId()).isTapped()&&f.bot.getManaPool().getMana().count()==2&&f.game.getState().getZone(c.getId())==Zone.HAND,"First action not separate Ring CC");check(f.bot.priority(f.game),"No conversion");check(f.game.getPermanent(nyk.getId()).isTapped()&&f.game.getState().getZone(c.getId())==Zone.HAND,"Converter did not return separately");cast(f,c,2);check(f.bot.getManaPool().getMana().count()==0,"Hybrid payment incorrect");});
  run("Restricted Gwenna mana cannot fund Nykthos input",()->{FourthSeatRealGameTest.Fixture f=fixture("a.AesiTyrantOfGyreStrait","Aesi, Tyrant of Gyre Strait");f.board("y.YevaNaturesHerald","Yeva, Nature's Herald");f.board("g.GoreclawTerrorOfQalSisma","Goreclaw, Terror of Qal Sisma");f.board("g.GwennaEyesOfGaea","Gwenna, Eyes of Gaea");f.board("n.NykthosShrineToNyx","Nykthos, Shrine to Nyx");Card c=f.hand("m.MurkfiendLiege","Murkfiend Liege");check(!fund(f,c.getSpellAbility()),"Creature-only input restriction flattened");reject(f,c);});
  for(int i=0;i<12;i++)run("Territory restricted output actual payment variant "+i,()->{FourthSeatRealGameTest.Fixture f=fixture("g.GishathSunsAvatar","Gishath, Sun's Avatar");Permanent territory=f.board("u.UnclaimedTerritory","Unclaimed Territory");f.game.getState().setValue(territory.getId()+"_type",SubType.DINOSAUR);f.board("a.ArcaneSignet","Arcane Signet");f.board("basiclands.Mountain","Mountain");Card c=f.hand("r.RhythmOfTheWild","Rhythm of the Wild");cast(f,c,2);check(f.bot.getManaPool().getMana().count()==0,"Ordinary 1RG payment incorrect");});
  for(String mode:new String[]{"dinosaur","colorless","invalid-green"})run("Territory preserves output boundary "+mode,()->{FourthSeatRealGameTest.Fixture f=fixture("g.GishathSunsAvatar","Gishath, Sun's Avatar");Permanent p=f.board("u.UnclaimedTerritory","Unclaimed Territory");f.game.getState().setValue(p.getId()+"_type",SubType.DINOSAUR);Card c=f.hand(mode.equals("dinosaur")?"s.SnappingSailback":mode.equals("colorless")?"s.SolRing":"r.RhythmOfTheWild",mode.equals("dinosaur")?"Snapping Sailback":mode.equals("colorless")?"Sol Ring":"Rhythm of the Wild");if(mode.equals("dinosaur"))f.bot.getManaPool().addMana(Mana.ColorlessMana(4),f.game,c.getSpellAbility());if(mode.equals("invalid-green")){f.board("basiclands.Mountain","Mountain");f.bot.getManaPool().addMana(Mana.ColorlessMana(1),f.game,c.getSpellAbility());check(!fund(f,c.getSpellAbility()),"Restricted G paid noncreature");reject(f,c);}else cast(f,c,2);});
  for(String card:new String[]{"c.Cultivate","t.TrailtrackerScout","w.WhispererOfTheWilds","i.IntrepidPaleontologist"})run("Castle cannot starve ordinary payment "+card,()->{FourthSeatRealGameTest.Fixture f=fixture("g.GoreclawTerrorOfQalSisma","Goreclaw, Terror of Qal Sisma");f.game.getCard(f.bot.getCommandersIds().iterator().next()).moveToZone(Zone.EXILED,null,f.game,false);f.board("c.CastleGarenbrig","Castle Garenbrig");f.board("y.YevaNaturesHerald","Yeva, Nature's Herald");f.board("s.SelvalaHeartOfTheWilds","Selvala, Heart of the Wilds");for(int j=0;j<(card.equals("c.Cultivate")?4:1);j++)f.board("basiclands.Forest","Forest");String name=card.equals("c.Cultivate")?"Cultivate":card.equals("t.TrailtrackerScout")?"Trailtracker Scout":card.equals("w.WhispererOfTheWilds")?"Whisperer of the Wilds":"Intrepid Paleontologist";Card c=f.hand(card,name);cast(f,c,4);});
  for(boolean enough:new boolean[]{false,true})run("Castle compound input Apex affordability enough="+enough,()->{FourthSeatRealGameTest.Fixture f=fixture("g.GishathSunsAvatar","Gishath, Sun's Avatar");f.board("y.YevaNaturesHerald","Yeva, Nature's Herald");Permanent castle=f.board("c.CastleGarenbrig","Castle Garenbrig");f.board("s.SolRing","Sol Ring");Card c=f.hand("a.ApexAltisaur","Apex Altisaur");f.bot.getManaPool().addMana(Mana.GreenMana(2),f.game,c.getSpellAbility());if(enough)for(int j=0;j<3;j++)f.board("basiclands.Forest","Forest");if(enough)cast(f,c,5);else{check(!fund(f,c.getSpellAbility()),"Compound 2GG counted as alternatives");reject(f,c);}ActivatedAbility converter=castle.getAbilities(f.game).getActivatedManaAbilities(Zone.BATTLEFIELD).stream().filter(a->a.getManaCosts().manaValue()==4).findFirst().get();check(converter.getManaCosts().manaValue()==4,"Live Castle cost rewritten");});
  run("Two distinct feeders before Castle reduced Apex",()->{FourthSeatRealGameTest.Fixture f=fixture("g.GishathSunsAvatar","Gishath, Sun's Avatar");f.board("y.YevaNaturesHerald","Yeva, Nature's Herald");f.board("g.GoreclawTerrorOfQalSisma","Goreclaw, Terror of Qal Sisma");f.board("r.RhonassMonument","Rhonas's Monument");f.board("c.CastleGarenbrig","Castle Garenbrig");f.board("s.SolRing","Sol Ring");f.board("basiclands.Forest","Forest");Card c=f.hand("a.ApexAltisaur","Apex Altisaur");f.bot.getManaPool().addMana(Mana.GreenMana(1),f.game,c.getSpellAbility());cast(f,c,5);check(f.bot.getManaPool().getMana().count()==0,"Reduced Apex exact6 payment wrong");});
  for(int devotion:new int[]{2,3})run("War Room real nested reservation devotion="+devotion,()->{for(int variant=0;variant<12;variant++){FourthSeatRealGameTest.Fixture f=fixture("a.AdelineResplendentCathar","Adeline, Resplendent Cathar");Card commander=f.game.getCard(f.bot.getCommandersIds().iterator().next());commander.moveToZone(Zone.BATTLEFIELD,null,f.game,false);if(devotion==3)f.board("l.LuminarchAscension","Luminarch Ascension");Permanent room=f.board("w.WarRoom","War Room");f.board("n.NykthosShrineToNyx","Nykthos, Shrine to Nyx");f.board("s.SolRing","Sol Ring");library(f,3);int hand=f.bot.getHand().size();ActivatedAbility draw=room.getAbilities(f.game).getActivatedAbilities(Zone.BATTLEFIELD).stream().filter(a->!a.isManaAbility()).findFirst().get();check(f.bot.activateAbility(draw,f.game),"Real War Room activation rejected");check(f.game.rollbackCount==0,"Nested converter caused rollback");check(f.game.getPermanent(room.getId()).isTapped()&&f.game.getPlayer(f.bot.getId()).getLife()==39,"Draw tap/life cost wrong");drain(f,10);check(f.bot.getHand().size()==hand+1,"War Room draw missing");}});
  for(String mode:new String[]{"large","large-haste","small","no-ferocious"})run("Fanatic actual same-source dominance "+mode,()->{FourthSeatRealGameTest.Fixture f=fixture("g.GhaltaPrimalHunger","Ghalta, Primal Hunger");if(!mode.equals("no-ferocious"))f.board("t.TopiaryStomper","Topiary Stomper");Permanent fanatic=f.board("f.FanaticOfRhonas","Fanatic of Rhonas");boolean large=mode.startsWith("large");if(mode.equals("large-haste")){FourthSeatRecoveredGroupTest.sick(fanatic);f.enemyBoard(0,"m.MassHysteria","Mass Hysteria");}if(large){f.board("h.HeirloomBlade","Heirloom Blade");f.board("s.SolRing","Sol Ring");f.board("basiclands.Forest","Forest");}Card c=f.hand(large?"v.VaultbornTyrant":"e.ElvishMystic",large?"Vaultborn Tyrant":"Elvish Mystic");check(fund(f,c.getSpellAbility()),"Legal Fanatic payment not funded");check(f.bot.activateAbility(c.getSpellAbility(),f.game),"Actual same-source output choice failed");check(f.game.getState().getZone(c.getId())==Zone.STACK&&f.game.rollbackCount==0,"Payment rolled back");if(!large)check(f.bot.getManaPool().getMana().count()==0,"One-green demand unnecessarily produced four");});
  finish("RECOVERED_MANA");
 }
}
